for (int i = 0; i < 3; i++)
{
    for (int j = 0; j < 3; j++)
    {
        if (i == 1 && j == 1) break outer;
        Console.WriteLine(i + "," + j);
    }
}

for (int i = 0; i < 2; i++)
{
    for (int j = 0; j < 3; j++)
    {
        if (j == 1) continue;
        Console.WriteLine(i + "," + j);
    }
}

int[] numbers = { 5, 8, 3, 9, 1 };
int target = 9;
for (int i = 0; i < numbers.Length; i++)
{
    if (numbers[i] == target)
    {
        Console.WriteLine("Found at index " + i);
        break;
    }
}

int[] scores = { 85, 40, 92, 30, 78 };
foreach (int score in scores)
{
    if (score < 60) continue;
    Console.WriteLine("Passed: " + score);
}

// break example - stops at 3
for (int i = 0; i < 5; i++)
{
    if (i == 3) break;
    Console.Write(i + " "); // 0 1 2
}

// continue example - skips 3
for (int i = 0; i < 5; i++)
{
    if (i == 3) continue;
    Console.Write(i + " "); // 0 1 2 4
}

for (int i = 0; i < data.Length; i++)
{
    if (data[i] == null) continue;
    Process(data[i]);
    if (data[i].IsLast) break;
}

